from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.Option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-1000, 1000)
            .Expiration(0, 730)
        )

        self._closes = RollingWindow[float](21)
        self._entry_order_id = None
        self._exit_order_id = None
        self._held_symbol = None
        self._held_expiry = None
        self._entry_fill_price = None
        self._expiration_block_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self._closes.Add(float(bar.Close))

        if self._closes.Count < 21:
            return

        current_fast = sum(self._closes[i] for i in range(5)) / 5.0
        current_slow = sum(self._closes[i] for i in range(20)) / 20.0
        previous_fast = sum(self._closes[i] for i in range(1, 6)) / 5.0
        previous_slow = sum(self._closes[i] for i in range(1, 21)) / 20.0

        if not (previous_fast <= previous_slow and current_fast > current_slow):
            return

        bar_end = bar.EndTime.time()
        if bar_end < time(9, 45) or bar_end > time(14, 30):
            return

        if self._expiration_block_date == self.Time.date():
            return

        if self._entry_order_id is not None or self._has_option_position():
            return

        self._try_enter_call(self.CurrentSlice, float(bar.Close))

    def OnData(self, data):
        if self.Portfolio[self.spy].Invested:
            quantity = self.Portfolio[self.spy].Quantity
            self.Debug(
                f"Unexpected SPY exercise/assignment position detected; liquidating {quantity} shares."
            )
            self.MarketOrder(self.spy, -quantity)

        if not self._has_option_position():
            return

        if self._held_expiry is not None and self.Time.date() >= self._held_expiry.date():
            self._expiration_block_date = self.Time.date()
            self._submit_exit("Expiration safeguard")
            return

        if (
            self._held_expiry is not None
            and self.Time.date() == self._previous_trading_day(self._held_expiry.date())
            and self.Time.time() == time(15, 45)
        ):
            self._submit_exit("Pre-expiration time stop")
            return

        if self._entry_fill_price is None or self._exit_order_id is not None:
            return

        quote = self._option_quote(data, self._held_symbol)
        if quote is None:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self._entry_fill_price:
            self._submit_exit(
                f"Profit target reached: midpoint {midpoint:.2f}, entry {self._entry_fill_price:.2f}"
            )

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self._entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self._entry_fill_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {self._held_symbol} at {self._entry_fill_price:.2f}"
                )
                self._entry_order_id = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry order {order_event.OrderId} did not fill: {order_event.Status}")
                self._entry_order_id = None
                self._held_symbol = None
                self._held_expiry = None
                self._entry_fill_price = None

        if order_event.OrderId == self._exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {float(order_event.FillPrice):.2f}"
                )
                self._exit_order_id = None
                self._held_symbol = None
                self._held_expiry = None
                self._entry_fill_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self._exit_order_id = None

    def _try_enter_call(self, slice_data, spy_price):
        if slice_data is None:
            self.Debug("Skipped entry: no current Slice available.")
            return

        chain = slice_data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no SPY option chain in current Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        contracts = list(chain)

        valid_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not valid_expiries:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        selected_expiry = valid_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped entry: no qualifying call for expiration {selected_expiry}."
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self._held_symbol = selected.Symbol
        self._held_expiry = selected.Expiry
        self._entry_fill_price = None
        ticket = self.MarketOrder(selected.Symbol, 1)
        self._entry_order_id = ticket.OrderId

        self.Debug(
            f"Entry submitted: {selected.Symbol}, strike {float(selected.Strike):.2f}, "
            f"expiry {selected.Expiry.date()}"
        )

    def _submit_exit(self, reason):
        if self._exit_order_id is not None or not self._has_option_position():
            return

        if self._exit_order_id is not None:
            self.Transactions.CancelOrder(self._exit_order_id)

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self._held_symbol, -quantity)
        self._exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {reason}; {self._held_symbol}")

    def _has_option_position(self):
        return (
            self._held_symbol is not None
            and self.Portfolio[self._held_symbol].Invested
        )

    def _option_quote(self, slice_data, symbol):
        if slice_data is None or symbol is None:
            return None

        chain = slice_data.OptionChains.get(self.option_symbol)
        if chain is None:
            return None

        for contract in chain:
            if contract.Symbol == symbol:
                bid = float(contract.BidPrice)
                ask = float(contract.AskPrice)
                if bid > 0 and ask > 0:
                    return bid, ask
                return None

        return None

    def _previous_trading_day(self, expiration_date):
        candidate = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

