        if self.held_contract is not None and self.entry_fill_price is not None:
            self.CheckProfitTarget(data)

        if data.Bars.ContainsKey(self.spy):
            self.five_minute_consolidator.Update(data.Bars[self.spy])

    def OnFiveMinuteBar(self, sender, bar):
        previous_fast = None
        previous_slow = None

        if self.closes.IsReady:
            previous_fast = sum(list(self.closes)[:5]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.Add(float(bar.Close))

        if not self.closes.IsReady or previous_fast is None:
            return

        current_fast = sum(list(self.closes)[:5]) / 5.0
        current_slow = sum(self.closes) / 20.0

        if not (previous_fast <= previous_slow and current_fast > current_slow):
            return

        end_time = bar.EndTime.time()
        if end_time < time(9, 45) or end_time > time(14, 30):
            return

        self.TryEnter(bar)

    def TryEnter(self, bar):
        if self.current_slice is None:
            self.Debug("Skipped entry: no current Slice.")
            return

        if self.no_entry_date == self.Time.date():
            self.Debug("Skipped entry: expiration safety blocked entries today.")
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Quantity != 0:
            self.Debug("Skipped entry: option position already exists.")
            return

        if self.entry_order_id is not None:
            self.Debug("Skipped entry: entry order is still open.")
            return

        if not self.current_slice.Bars.ContainsKey(self.spy):
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        chain = self.current_slice.OptionChains.get(self.option_canonical)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call and contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no qualifying call expiration.")
            return

        expiry = expiries[0]
        spot = float(self.current_slice.Bars[self.spy].Close)
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike at selected expiration.")
            return

        selected = min(candidates, key=lambda c: (float(c.Strike), str(c.Symbol)))

        self.held_contract = selected.Symbol
        self.held_expiry = expiry
        self.entry_fill_price = None
        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId

        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {expiry}, "
            f"strike {selected.Strike}."
        )

    def CheckProfitTarget(self, data):
        if self.HasOpenExitOrder():
            return

        quote = data.QuoteBars.get(self.held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.CancelOtherOpenExitOrders()
            self.Debug(
                f"Profit target reached for {self.held_contract}: "
                f"midpoint {midpoint:.2f}."
            )
            self.SubmitExitOrder("profit target")

    def CheckTimeStop(self):
        if self.held_contract is None or self.held_expiry is None:
            return

        if self.Portfolio[self.held_contract].Quantity == 0:
            return

        next_trading_day = self.Securities[self.spy].Exchange.Hours.GetNextTradingDay(self.Time)
        if next_trading_day.date() == self.held_expiry:
            if not self.HasOpenExitOrder():
                self.CancelOtherOpenExitOrders()
                self.Debug(f"15:45 pre-expiration exit for {self.held_contract}.")
                self.SubmitExitOrder("pre-expiration time stop")

    def SubmitExitOrder(self, reason):
        if self.held_contract is None or self.HasOpenExitOrder():
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_contract}.")

    def HasOpenExitOrder(self):
        if self.exit_order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
        if ticket is None:
            return False

        return ticket.Status in [OrderStatus.New, OrderStatus.Submitted, OrderStatus.PartiallyFilled]

    def CancelOtherOpenExitOrders(self):
        if self.held_contract is None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if self.exit_order_id is None or order.Id != self.exit_order_id:
                self.Transactions.CancelOrder(order.Id)

    def OnOrderEvent(self, orderEvent):
        if self.entry_order_id is not None and orderEvent.OrderId == self.entry_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.entry_fill_price = float(orderEvent.FillPrice)
                self.Debug(
                    f"Entry filled: {self.held_contract} at "
                    f"{self.entry_fill_price:.2f}."
                )
                self.entry_order_id = None
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry order did not fill: {self.held_contract}.")
                self.entry_order_id = None
                self.held_contract = None
                self.held_expiry = None
                self.entry_fill_price = None

        if self.exit_order_id is not None and orderEvent.OrderId == self.exit_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self.held_contract} at {orderEvent.FillPrice:.2f}.")
                self.exit_order_id = None
                self.held_contract = None
                self.held_expiry = None
                self.entry_fill_price = None
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

