from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        spy = self.AddEquity("SPY", Resolution.Minute)
        spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(lambda universe: universe.Strikes(-100, 100).Expiration(0, 365))

        self.fast = SimpleMovingAverage("SPY_5m_Fast", 5)
        self.slow = SimpleMovingAverage("SPY_5m_Slow", 20)

        self.entry_order_id = None
        self.exit_order_id = None
        self.held_contract = None
        self.entry_fill_price = None
        self.block_entries_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy_symbol, consolidator)

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy_symbol),
            self.TimeRules.At(15, 45),
            self.OnTimeStop
        )

    def OnData(self, data):
        today = self.Time.date()
        if self.block_entries_date != today:
            self.block_entries_date = None

        if self.Portfolio[self.spy_symbol].Quantity != 0:
            quantity = self.Portfolio[self.spy_symbol].Quantity
            self.Debug(f"Unexpected SPY exercise/assignment position: {quantity}; liquidating.")
            if not self.HasOpenOrder(self.spy_symbol):
                self.MarketOrder(self.spy_symbol, -quantity)

        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            if self.held_contract.ID.Date == today:
                self.block_entries_date = today
                self.Debug(f"Expiration-day option holding detected: {self.held_contract}; liquidating.")
                self.SubmitExit("expiration safeguard")
                return

            self.CheckProfitTarget(data)

    def OnFiveMinuteBar(self, bar):
        prior_fast = self.fast.Current.Value
        prior_slow = self.slow.Current.Value
        was_ready = self.fast.IsReady and self.slow.IsReady

        self.fast.Update(IndicatorDataPoint(bar.EndTime, bar.Close))
        self.slow.Update(IndicatorDataPoint(bar.EndTime, bar.Close))

        if not was_ready:
            return

        bullish_cross = (
            prior_fast <= prior_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )
        if not bullish_cross:
            return

        end_minutes = bar.EndTime.hour * 60 + bar.EndTime.minute
        if end_minutes < 9 * 60 + 45 or end_minutes > 14 * 60 + 30:
            return

        if self.block_entries_date == self.Time.date():
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            return

        if self.entry_order_id is not None and self.IsOrderOpen(self.entry_order_id):
            return

        self.entry_order_id = None
        self.TryEnterFromCurrentSlice()

    def TryEnterFromCurrentSlice(self):
        data = self.CurrentSlice
        if data is None or self.option_symbol not in data.OptionChains:
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        chain = data.OptionChains[self.option_symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call and contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Entry skipped: no call expiration at least seven calendar days away.")
            return

        selected_expiry = expiries[0]
        spy_price = self.Securities[self.spy_symbol].Price
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying 1% OTM call at selected expiration.")
            return

        selected = sorted(candidates, key=lambda c: (c.Strike, str(c.Symbol)))[0]
        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def CheckProfitTarget(self, data):
        if self.entry_fill_price is None or self.HasOpenExitOrder():
            return

        if self.held_contract not in data.QuoteBars:
            return

        quote = data.QuoteBars[self.held_contract]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2
        if midpoint >= self.entry_fill_price * 1.50:
            self.SubmitExit("50% profit target")

    def OnTimeStop(self):
        if self.held_contract is None or not self.Portfolio[self.held_contract].Invested:
            return

        expiry_date = self.held_contract.ID.Date
        if self.PreviousTradingDay(expiry_date) == self.Time.date():
            self.SubmitExit("pre-expiration 15:45 time stop")

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        hours = self.Securities[self.spy_symbol].Exchange.Hours

        while not hours.IsDateOpen(candidate, False):
            candidate -= timedelta(days=1)

        return candidate

    def SubmitExit(self, reason):
        if self.held_contract is None or not self.Portfolio[self.held_contract].Invested:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self.held_contract].Quantity
        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_contract}")

    def OnOrderEvent(self, order_event):
        if self.entry_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(f"Entry filled: {order_event.Symbol} at {order_event.FillPrice}")
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_order_id = None

        if self.exit_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice}")
                self.exit_order_id = None
                self.held_contract = None
                self.entry_fill_price = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

    def IsOrderOpen(self, order_id):
        order = self.Transactions.GetOrderById(order_id)
        return order is not None and order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def HasOpenOrder(self, symbol):
        return len(self.Transactions.GetOpenOrders(symbol)) > 0

    def HasOpenExitOrder(self):
        return self.exit_order_id is not None and self.IsOrderOpen(self.exit_order_id)

